<?php
require_once __DIR__.'/functions.php';$u=require_login();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['file_id']??0);$s=db()->prepare('SELECT id FROM files WHERE id=? AND user_id=?');$s->execute([$id,$u['id']]);if(!$s->fetch()){flash('File tidak ditemukan.','error');redirect('dashboard.php');}$token=bin2hex(random_bytes(24));$hash=hash('sha256',$token);$s=db()->prepare('INSERT INTO shares(file_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(), INTERVAL 7 DAY))');$s->execute([$id,$hash]);$url=(isset($_SERVER['HTTPS'])?'https':'http').'://'.$_SERVER['HTTP_HOST'].rtrim(dirname($_SERVER['SCRIPT_NAME']),'/').'/public_share.php?token='.$token;page_header('Link berbagi');?><section class="auth-card"><h1>Link berbagi dibuat</h1><p>Link ini berlaku selama 7 hari. Siapa pun yang memiliki link dapat mengunduh file.</p><div class="share-url"><?=e($url)?></div><button class="primary full" onclick="navigator.clipboard.writeText(<?=json_encode($url)?>).then(()=>alert('Link disalin'))">Salin link</button><p><a href="dashboard.php">Kembali ke dashboard</a></p></section><?php page_footer();exit;}redirect('dashboard.php');
